ruleHooks.extraMethods:
; Obter Próximo Código do Checklist
;
; set sc=$$ObterProximoChecklist^WDOMTESTEROM100ARG(codEmpresa,.codChecklist)
ObterProximoChecklist(codEmpresa,codChecklist)	;
$$$VAR
;
set codChecklist=$increment(^WDOMTESTEROMC(1,codEmpresa,0))
;
quit $$$OK
;
; Obter Tabela de Checklists (F7 de cadastrados)
;
; set sc=$$ObterTabChecklist^WDOMTESTEROM100ARG(codEmpresa,.tabChecklist)
ObterTabChecklist(codEmpresa,tabChecklist)	;
$$$VAR
new sc,codChecklist,dados,ftcl,situacao
;
kill tabChecklist
set codChecklist=""
for  set codChecklist=$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist)) quit:codChecklist=""  do
. set dados=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1))
. set ftcl=""
. if $piece(dados,Z,5)'="" set sc=$$ObterNomeCliente^CCFT760RG(codEmpresa,$piece(dados,Z,5),.ftcl)
. set situacao=$select($piece(dados,Z,3)="E":"Encerrado",1:"Aberto")
. set tabChecklist(codChecklist)=$piece(ftcl,Z,2)_" ("_situacao_")"
;
quit $$$OK
;
; Validar Pedido do Checklist
;
; set sc=$$ValidarPedidoChecklist^WDOMTESTEROM100ARG(codEmpresa,codCliente,codPedido)
ValidarPedidoChecklist(codEmpresa,codCliente,codPedido)	;
$$$VAR
new sc,pvpd
;
if $get(codCliente)="" quit $$$ERROR(10000,"Informe o cliente na aba Dados Gerais!")
set sc=$$VerPedido^CCPVRG001(codEmpresa,codPedido,"",.pvpd)
if $$$ISERR(sc) quit sc
if $piece(pvpd,Z,1)'=codCliente quit $$$ERROR(10000,"Pedido "_codPedido_" não é do cliente "_codCliente_"!")
if '$data(^PVCL(codEmpresa,codCliente,codPedido)) quit $$$ERROR(10000,"Pedido "_codPedido_" não está em aberto!")
;
quit $$$OK
;
; Incluir Itens no Checklist (pedido: todos os itens; produto: uma linha por unidade)
;
; set sc=$$IncluirItensChecklist^WDOMTESTEROM100ARG(codEmpresa,codChecklist,codPedido,codProduto,quantidade)
IncluirItensChecklist(codEmpresa,codChecklist,codPedido,codProduto,quantidade)	;
$$$VAR
new sc,dataHora,codOperador,codItem,pvpd,codSequencia,contador,dados
;
if $get(codChecklist)="" quit $$$ERROR(10000,"Salve o checklist antes de incluir itens!")
if $get(codPedido)="",$get(codProduto)="" quit $$$ERROR(10000,"Informe o pedido ou o produto!")
;
set sc=$$$OK
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
set codSequencia=+$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,""),-1)
;
if $get(codPedido)'="" do  quit sc
. set codItem=""
. for  set codItem=$order(^PVPD(codEmpresa,codPedido,codItem)) quit:codItem=""!$$$ISERR(sc)  do
. . set sc=$$VerPedido^CCPVRG001(codEmpresa,codPedido,codItem,.pvpd)
. . quit:$$$ISERR(sc)
. . set codSequencia=codSequencia+1
. . set dados=dataHora_Z_codOperador_Z_codPedido_Z_codItem_Z_$piece(pvpd,Z,1)_Z_$piece(pvpd,Z,2)
. . do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia),dados)
;
if +$get(quantidade)<1 quit $$$ERROR(10000,"Quantidade: Campo obrigatório!")
;
for contador=1:1:quantidade do
. set codSequencia=codSequencia+1
. set dados=dataHora_Z_codOperador_Z_""_Z_""_Z_codProduto_Z_1
. do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia),dados)
;
quit $$$OK
;
; Remover Item do Checklist (grava o histórico com a justificativa)
;
; set sc=$$RemoverItemChecklist^WDOMTESTEROM100ARG(codEmpresa,codChecklist,codSequencia,justificativa)
RemoverItemChecklist(codEmpresa,codChecklist,codSequencia,justificativa)	;
$$$VAR
new dados,codPedido,codItem,codRomaneio,codSequenciaHistorico,historico
;
if $get(codSequencia)="" quit $$$ERROR(10000,"Selecione um item do grid!")
if '$data(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia)) quit $$$ERROR(10000,"Item "_codSequencia_" não encontrado!")
;
set dados=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia))
set codPedido=$piece(dados,Z,3)
set codItem=$piece(dados,Z,4)
set codRomaneio=$$ObterRomaneioItem(codEmpresa,codPedido,codItem)
if codRomaneio'="" quit $$$ERROR(10000,"Item está no romaneio "_codRomaneio_". Remova o item do romaneio antes de excluir do checklist!")
;
set codSequenciaHistorico=+$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,3,""),-1)+1
set historico=$$$horologEmp(codEmpresa)_Z_$$VEROP^%CSUTIUD(1)
set historico=historico_Z_"Exclusão do item "_codSequencia_" ("_$select(codPedido'="":"pedido "_codPedido_"/"_codItem,1:"produto "_$piece(dados,Z,5))_")"
set historico=historico_Z_$translate($get(justificativa),Z," ")
do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,3,codSequenciaHistorico),historico)
do $$$KillG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia))
;
quit $$$OK
;
; Obter Romaneio do Item do Pedido ("" se não estiver em romaneio)
;
; set codRomaneio=$$ObterRomaneioItem^WDOMTESTEROM100ARG(codEmpresa,codPedido,codItem)
ObterRomaneioItem(codEmpresa,codPedido,codItem)	;
$$$VAR
new codRomaneio,itemRomaneio,romaneioItem
;
if $get(codPedido)=""!($get(codItem)="") quit ""
;
set (codRomaneio,romaneioItem)=""
for  set codRomaneio=$order(^PVPRCP(codEmpresa,codPedido,codRomaneio)) quit:codRomaneio=""!(romaneioItem'="")  do
. set itemRomaneio=""
. for  set itemRomaneio=$order(^PVBROM(codEmpresa,codRomaneio,itemRomaneio)) quit:itemRomaneio=""!(romaneioItem'="")  do
. . if $piece($get(^PVBROM(codEmpresa,codRomaneio,itemRomaneio)),Z,20)=codItem set romaneioItem=codRomaneio
;
quit romaneioItem
;
; Verificar Romaneio em Execução no Checklist (mensagem informativa)
;
; set sc=$$VerificarRomaneioAberto^WDOMTESTEROM100ARG(codEmpresa,codChecklist)
VerificarRomaneioAberto(codEmpresa,codChecklist)	;
$$$VAR
new codSequencia,codPedido,codRomaneio,romaneioAberto
;
set (codSequencia,romaneioAberto)=""
for  set codSequencia=$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia)) quit:codSequencia=""!(romaneioAberto'="")  do
. set codPedido=$piece($get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia)),Z,3)
. quit:codPedido=""
. set codRomaneio=""
. for  set codRomaneio=$order(^PVPRCP(codEmpresa,codPedido,codRomaneio)) quit:codRomaneio=""!(romaneioAberto'="")  do
. . if $piece($get(^PVPRCP(codEmpresa,codPedido,codRomaneio)),Z,1)<2 set romaneioAberto=codRomaneio
;
if romaneioAberto'="" quit $$$ERROR(10000,"Atenção: o checklist está sendo concluído com o romaneio "_romaneioAberto_" ainda não concluído!")
;
quit $$$OK
;
; Encerrar Checklist
;
; set sc=$$EncerrarChecklist^WDOMTESTEROM100ARG(codEmpresa,codChecklist,observacao)
EncerrarChecklist(codEmpresa,codChecklist,observacao)	;
$$$VAR
new dados
;
if '$data(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1)) quit $$$ERROR(10000,"Salve o checklist antes de encerrar!")
;
set dados=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1))
if $piece(dados,Z,3)="E" quit $$$ERROR(10000,"Checklist "_codChecklist_" já está encerrado!")
;
set $piece(dados,Z,3)="E"
set $piece(dados,Z,7)=$$$horologEmp(codEmpresa)
set $piece(dados,Z,8)=+$horolog
set $piece(dados,Z,9)=$$VEROP^%CSUTIUD(1)
set $piece(dados,Z,10)=$translate($get(observacao),Z," ")
do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1),dados)
;
quit $$$OK
;
; Obter Código Editado do Produto (0000000.000.0000)
;
; set codEditado=$$ObterCodigoEditado^WDOMTESTEROM100ARG(codEmpresa,codItem)
ObterCodigoEditado(codEmpresa,codItem)	;
$$$VAR
new sc,codEditado,codItemPai
;
if $get(codItem)="" quit ""
set sc=$$VerReferenciaItem^CCCGIRG001(codEmpresa,"",codItem,.codEditado,.codItemPai)
if $$$ISERR(sc)!($get(codEditado)="") quit codItem
;
quit codEditado
;
; Obter Referência do Produto (código pai 0000000)
;
; set referencia=$$ObterReferenciaItem^WDOMTESTEROM100ARG(codEmpresa,codItem)
ObterReferenciaItem(codEmpresa,codItem)	;
$$$VAR
;
quit $piece($$ObterCodigoEditado(codEmpresa,$get(codItem)),".",1)
;
; Obter Descrição do Produto
;
; set descricao=$$ObterDescricaoProduto^WDOMTESTEROM100ARG(codEmpresa,codItem)
ObterDescricaoProduto(codEmpresa,codItem)	;
$$$VAR
new sc,cgigen
;
if $get(codItem)="" quit ""
set sc=$$VerItemCGIGEN^CCCGIRG001(codEmpresa,codItem,.cgigen)
if $$$ISERR(sc) quit ""
;
quit $piece(cgigen,Z,1)
